// ===== Utilidades comunes del orquestador (se copian en los nodos Code) =====
// Tarifa verificada en https://ai.google.dev/gemini-api/docs/pricing el 2026-11-03. Vuelve a verificarla al implementar.
const CFG_LLM = {
  URL: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
  PROVEEDOR: 'Google Gemini API',
  MODELO: 'gemini-3.1-flash-lite',
  TARIFA_IN: 0.25,   // USD por 1M tokens de entrada
  TARIFA_OUT: 1.50   // USD por 1M tokens de salida
};

function ahora() { return new Date().toISOString(); }

// Seudónimo no reversible a simple vista (FNV-1a). No es criptográfico: solo evita mostrar IDs reales.
function seudonimo(v) {
  let h = 0x811c9dc5; const s = String(v);
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return 'u_' + h.toString(16).padStart(8, '0');
}

const PATRONES_INYECCION = [
  /ignor(a|ar|en|e)\s+(las\s+|todas\s+las\s+|tus\s+)?(instrucciones|reglas|pol[ií]ticas)/i,
  /ignore\s+(all\s+|previous\s+|the\s+)?(instructions|rules)/i,
  /(revela|muestra|dame|imprime|env[ií]a).{0,30}(token|clave|api.?key|secret|contrase[nñ]a|prompt)/i,
  /system\s*prompt|prompt\s+de\s+sistema/i,
  /(desactiva|apaga|omite|salta).{0,30}(control|regla|guardrail|revis|aprobaci)/i,
  /(act[uú]a|finge)\s+como\s+(administrador|desarrollador|root)/i,
  /<\s*script|javascript:|https?:\/\//i
];
function detectarInyeccion(texto) { return PATRONES_INYECCION.some(p => p.test(String(texto || ''))); }

function parseJsonLLM(texto) {
  if (typeof texto !== 'string') return null;
  const t = texto.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) {
    const a = t.indexOf('{'), b = t.lastIndexOf('}');
    if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e2) { /* sigue */ } }
    return null;
  }
}

function costoUSD(tin, tout) { return (tin * CFG_LLM.TARIFA_IN + tout * CFG_LLM.TARIFA_OUT) / 1000000; }

function traza(s, agente, estado, resumen) {
  s.traza.push({ ts: ahora(), caso_id: s.caso_id, agente, estado, resumen: String(resumen).slice(0, 300) });
}

// Loop de seguridad y costo: evalúa permisos/presupuesto ANTES de llamar al modelo.
function prepararLlamada(s, agente, etapa, system, user, maxTokens) {
  const messages = [ { role: 'system', content: system }, { role: 'user', content: user } ];
  const estIn = Math.ceil(JSON.stringify(messages).length / 4);
  const reserva = 1.2; // margen del 20 %
  const estCosto = costoUSD(estIn, maxTokens) * reserva;
  if (s.llamadas >= s.max_llamadas) return { ok: false, motivo: 'Límite de llamadas alcanzado (' + s.max_llamadas + ')' };
  if (s.gastado_usd + estCosto > s.limite_costo_usd) {
    return { ok: false, motivo: 'Presupuesto insuficiente: gastado ' + s.gastado_usd.toFixed(6) + ' + estimado ' + estCosto.toFixed(6) + ' > límite ' + s.limite_costo_usd + ' USD' };
  }
  if (Date.now() - s.t_inicio_ms > s.tiempo_limite_ms) return { ok: false, motivo: 'Tiempo límite del caso agotado' };
  s.llamadas += 1;
  s.llamada_actual = {
    llamada_id: s.caso_id + '-' + agente + '-' + String(s.llamadas).padStart(2, '0'),
    agente, etapa, t0: Date.now(), est_in: estIn, max_tokens: maxTokens,
    reintento: (agente === 'A3' && s.iter_calidad > 0) ? 1 : 0
  };
  s.llm_request = { model: CFG_LLM.MODELO, messages, temperature: 0.2, max_tokens: maxTokens, response_format: { type: 'json_object' } };
  traza(s, 'ORQ', 'invoca', agente + ' (' + s.llamada_actual.llamada_id + '), estimado ' + estCosto.toFixed(6) + ' USD');
  return { ok: true };
}

// Registra consumo medido (usage del proveedor) o estimado si no viene.
function registrarRespuesta(s, r) {
  const c = s.llamada_actual || { llamada_id: s.caso_id + '-X', agente: '?', etapa: '?', t0: Date.now(), est_in: 0, reintento: 0 };
  const dur = Date.now() - c.t0;
  let estado = 'ok', contenido = null, tin, tout, origen = 'medido';
  if (!r || r.error || !Array.isArray(r.choices) || !r.choices.length) estado = 'error_api';
  else contenido = (r.choices[0].message || {}).content || null;
  if (r && r.usage && Number.isFinite(r.usage.prompt_tokens)) {
    tin = r.usage.prompt_tokens; tout = r.usage.completion_tokens || 0;
  } else {
    tin = c.est_in; tout = estado === 'ok' ? Math.ceil(String(contenido || '').length / 4) : 0; origen = 'estimado';
  }
  const usd = costoUSD(tin, tout);
  s.gastado_usd += usd;
  s.costos.push({
    fecha_hora: ahora(), caso_id: s.caso_id, llamada_id: c.llamada_id, etapa: c.etapa, agente: c.agente,
    proveedor: CFG_LLM.PROVEEDOR, modelo: CFG_LLM.MODELO, tokens_entrada: tin, tokens_salida: tout, tokens_cache: 0,
    duracion_voz_s: '', unidad_cobro: 'USD por 1M tokens', tarifa_entrada: CFG_LLM.TARIFA_IN, tarifa_salida: CFG_LLM.TARIFA_OUT,
    costo: Number(usd.toFixed(8)), moneda: 'USD', estado, reintento: c.reintento, origen, duracion_ms: dur
  });
  delete s.llm_request; delete s.llamada_actual;
  return { estado, json: estado === 'ok' ? parseJsonLLM(contenido) : null, dur, llamada_id: c.llamada_id };
}

function salida(s, agente, estado, resultado, fuentes, advertencias, dur, ref) {
  const o = { caso_id: s.caso_id, agente, estado, resultado, fuentes: fuentes || [], advertencias: advertencias || [], duracion_ms: dur || 0, ref_consumo: ref || null };
  s.salidas[agente] = o;
  return o;
}

function detener(s, estado, motivo) {
  s.estado = estado; s.motivo_cierre = motivo; s.siguiente = 'cierre';
  traza(s, 'ORQ', estado, motivo);
}

function copia(o) { return JSON.parse(JSON.stringify(o)); }

// ===== Reglas deterministas de PapelSur (fuente única) =====
// Se copia dentro de los nodos Code de n8n y se prueba en GitHub Actions (tests/test_reglas.js).
const POLITICA = {
  version: 'politica_comercial v1.0',
  IVA: 0.16,
  ENVIO_MXN: 250,
  ENVIO_GRATIS_DESDE: 3000,
  DESCUENTOS: [ { desde: 15000, pct: 0.08 }, { desde: 5000, pct: 0.05 } ],
  DESCUENTO_MAX: 0.10,
  MAX_TOTAL_MXN: 100000,
  MAX_CANTIDAD: 5000,
  MAX_PARTIDAS: 20,
  VIGENCIA_DIAS: 7,
  ETIQUETA: 'RESULTADO SIMULADO'
};

function r2(x) { return Math.round((x + Number.EPSILON) * 100) / 100; }

// lineas: [{ sku, descripcion, cantidad, precio_unitario, existencia }]
function calcularCotizacion(lineas, P = POLITICA) {
  const errores = [];
  const advertencias = [];
  const detalle = [];
  if (!Array.isArray(lineas) || lineas.length === 0) errores.push('Sin líneas para cotizar');
  if (Array.isArray(lineas) && lineas.length > P.MAX_PARTIDAS) errores.push('Más de ' + P.MAX_PARTIDAS + ' partidas');
  for (const l of (lineas || [])) {
    const cant = l.cantidad;
    if (!Number.isInteger(cant) || cant < 1 || cant > P.MAX_CANTIDAD) { errores.push('Cantidad inválida en ' + l.sku); continue; }
    if (!(typeof l.precio_unitario === 'number' && l.precio_unitario > 0)) { errores.push('Precio inválido en ' + l.sku); continue; }
    const existencia = Number.isInteger(l.existencia) ? l.existencia : 0;
    if (existencia < cant) advertencias.push(l.sku + ': existencia ' + existencia + ' de ' + cant + ' solicitadas (entrega parcial o pedido especial)');
    detalle.push({ sku: l.sku, descripcion: l.descripcion, cantidad: cant, precio_unitario: l.precio_unitario, importe: r2(cant * l.precio_unitario) });
  }
  const subtotal = r2(detalle.reduce((a, d) => a + d.importe, 0));
  let pct = 0;
  for (const d of P.DESCUENTOS) { if (subtotal >= d.desde) { pct = d.pct; break; } }
  pct = Math.min(pct, P.DESCUENTO_MAX);
  const descuento = r2(subtotal * pct);
  const base = r2(subtotal - descuento);
  const envio = subtotal >= P.ENVIO_GRATIS_DESDE ? 0 : (detalle.length ? P.ENVIO_MXN : 0);
  const iva = r2((base + envio) * P.IVA);
  const total = r2(base + envio + iva);
  return {
    detalle, subtotal, descuento_pct: pct, descuento, envio, iva, total, moneda: 'MXN',
    requiere_escalar: total > P.MAX_TOTAL_MXN, errores, advertencias, politica: P.version
  };
}

// Revisión determinista del agente 4. Devuelve lista de fallas (vacía = pasa).
function verificarPropuesta(prop, catalogoItems, P = POLITICA) {
  const f = [];
  if (!prop || typeof prop !== 'object') return ['Propuesta ausente'];
  const porSku = {};
  for (const it of (catalogoItems || [])) porSku[it.sku] = it;
  for (const l of (prop.lineas || [])) {
    const c = porSku[l.sku];
    if (!c) f.push('SKU fuera del catálogo autorizado: ' + l.sku);
    else if (c.precio_mxn !== l.precio_unitario) f.push('Precio de ' + l.sku + ' no coincide con catálogo');
  }
  const recalculo = calcularCotizacion((prop.lineas || []).map(l => ({ ...l, existencia: (porSku[l.sku] || {}).existencia })), P);
  if (recalculo.total !== prop.total) f.push('Total no coincide con el recálculo (' + recalculo.total + ' vs ' + prop.total + ')');
  if (prop.descuento_pct > P.DESCUENTO_MAX) f.push('Descuento mayor al máximo de política');
  if (prop.vigencia_dias !== P.VIGENCIA_DIAS) f.push('Vigencia distinta de ' + P.VIGENCIA_DIAS + ' días');
  if (prop.etiqueta !== P.ETIQUETA) f.push('Falta la etiqueta RESULTADO SIMULADO');
  if (!Array.isArray(prop.supuestos) || prop.supuestos.length < 2) f.push('Faltan supuestos explícitos (mínimo 2)');
  const resumen = String(prop.resumen || '');
  if (resumen.length < 40 || resumen.length > 900) f.push('Resumen fuera de longitud (40 a 900 caracteres)');
  const texto = resumen + ' ' + (prop.supuestos || []).join(' ') + ' ' + (prop.condiciones || []).join(' ');
  if (/[\w.+-]+@[\w-]+\.[\w.]+/.test(texto) || /\b\d{10}\b/.test(texto)) f.push('El texto contiene datos personales (correo o teléfono)');
  if (/(cr[eé]dito|pago a \d+ d[ií]as|garantizad)/i.test(texto)) f.push('Promete condiciones no autorizadas (crédito o garantías)');
  if (!Array.isArray(prop.fuentes) || !prop.fuentes.some(x => /catalogo/i.test(x))) f.push('No cita el catálogo como fuente');
  return f;
}

try { if (typeof module !== 'undefined' && module.exports) module.exports = { POLITICA, r2, calcularCotizacion, verificarPropuesta }; } catch (e) { /* entorno n8n */ }

// Nodo: «Guardrails voz». Modo: Run Once for All Items.
// El webhook ya exige el encabezado secreto (credencial Header Auth). Aquí se validan campos y permisos.
const CFG = {
  APROBADOR_CHAT_ID: 'REEMPLAZAR_CHAT_ID_DEL_APROBADOR', // a quién llegan los botones de casos creados por voz (no publicar)
  LIMITE_COSTO_USD: 0.02, MAX_LLAMADAS: 10, TIEMPO_LIMITE_MS: 120000, MAX_TEXTO: 600, MINUTOS_EXPIRACION: 30
};
const b = ($input.first().json.body) || {};
const accion = String(b.accion || '').toLowerCase();
const base = { cfg: CFG, canal: 'voz', usuario: 'voz_publica', chat_id: CFG.APROBADOR_CHAT_ID };
const error = (msg) => [{ json: { ...base, ruta: 2, respuesta: { ok: false, mensaje: msg } } }];

// Deduplicación de reintentos del proveedor (misma petición en el mismo minuto)
const sd = $getWorkflowStaticData('global'); sd.vistos = sd.vistos || [];
const clave = 'voz:' + seudonimo(JSON.stringify(b) + new Date().toISOString().slice(0, 16));
if (sd.vistos.includes(clave)) return error('Solicitud duplicada; ya se está procesando.');
sd.vistos.push(clave); if (sd.vistos.length > 1000) sd.vistos = sd.vistos.slice(-1000);

if (accion === 'consultar') {
  const folio = String(b.folio || '').toUpperCase().replace(/\s+/g, '');
  if (!/^PS-\d{8}-[A-Z0-9]{4}$/.test(folio)) return error('El folio debe tener el formato PS, fecha de ocho dígitos y cuatro caracteres. Pide al usuario que lo repita.');
  return [{ json: { ...base, ruta: 0, caso_id: folio, evento_id: clave } }];
}
if (accion === 'crear') {
  const texto = String(b.solicitud || '').trim();
  if (texto.length < 5 || texto.length > CFG.MAX_TEXTO) return error('La solicitud está vacía o es demasiado larga. Pide productos y cantidades.');
  if (detectarInyeccion(texto)) return error('Solicitud bloqueada por política: solo se aceptan productos y cantidades.');
  return [{ json: { ...base, ruta: 1, texto, evento_id: clave } }];
}
return error('Acción no permitida. Usa consultar o crear.');

// ===== Nodo «Respuesta consulta voz» (Run Once for All Items) =====
// __CONSULTA__
const g = $('Guardrails voz').first().json;
const filas = $input.all().map(i => i.json).filter(f => f && f.caso_id === g.caso_id);
if (!filas.length) return [{ json: { respuesta: { ok: false, folio: g.caso_id, mensaje: 'No existe ese folio en el registro de prueba. No inventes un estado.' } } }];
const f = filas[filas.length - 1];
return [{ json: { respuesta: { ok: true, folio: f.caso_id, estado: f.estado, version: Number(f.version), total_mxn: Number(f.total_mxn), actualizado: f.actualizado, nota: 'RESULTADO SIMULADO de empresa ficticia' } } }];

// Nodo: «Crear caso». Modo: Run Once for All Items.
// Entrada: salida de guardrails (Telegram o voz). Salida: EXACTAMENTE las columnas de la tabla «casos».
const g = $input.first().json;
const d = new Date();
const fecha = d.toISOString().slice(0, 10).replace(/-/g, '');
const alfabeto = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let suf = ''; for (let i = 0; i < 4; i++) suf += alfabeto[Math.floor(Math.random() * alfabeto.length)];
const caso_id = 'PS-' + fecha + '-' + suf;
const entrada = {
  caso_id,
  canal: g.canal || 'telegram',
  usuario: g.usuario,
  objetivo: 'cotizacion',
  texto: g.texto,
  modo: 'SIMULADO',
  limite_costo_usd: g.cfg.LIMITE_COSTO_USD,
  max_llamadas: g.cfg.MAX_LLAMADAS,
  tiempo_limite_ms: g.cfg.TIEMPO_LIMITE_MS,
  minutos_expiracion: g.cfg.MINUTOS_EXPIRACION,
  demo_v1: /#demo-loop/i.test(g.texto || ''),
  evento_id: g.evento_id,
  creado: d.toISOString()
};
return [{ json: {
  caso_id,
  canal: entrada.canal,
  usuario: g.usuario,
  chat_id: String(g.chat_id || ''),
  estado: 'recibido',
  version: 0,
  texto: g.texto,
  entrada_json: JSON.stringify(entrada),
  resultado_json: '',
  total_mxn: 0,
  expira_en: '',
  nonce: '',
  decision: '',
  decision_por: '',
  costo_usd: 0,
  evento_id: g.evento_id,
  creado: entrada.creado,
  actualizado: entrada.creado
} }];

// (Run Once for All Items) =====
// __CREACION__
const c = $('Crear caso (voz)').first().json;
return [{ json: { respuesta: { ok: true, folio: c.caso_id, estado: 'en_proceso', mensaje: 'Caso creado. La propuesta se revisa y la aprueba una persona por Telegram. Consulta el folio en un minuto.' } } }];

// Nodo: «Registro de resultado». Modo: Run Once for All Items.
// $json = respuesta del orquestador. Prepara fila del caso, filas de costo y mensaje de aprobación.
const res = $input.first().json;
const caso = $("Crear caso (voz)").first().json;               // fila creada al inicio (incluye chat_id privado)
const chatDestino = caso.chat_id;                      // Telegram: chat del solicitante; Voz: chat del aprobador
const ahoraIso = new Date().toISOString();
const p = res.propuesta;
const nonce = Math.random().toString(36).slice(2, 8).padEnd(6, '0');
const expira = new Date(Date.now() + (res.minutos_expiracion || 30) * 60000).toISOString();
const resultadoPrivado = { estado: res.estado, motivo: res.motivo, propuesta: p, historial_versiones: res.historial_versiones, traza: res.traza, resumen_costos: res.resumen_costos, duracion_ms: res.duracion_ms };
const fila_caso = {
  caso_id: res.caso_id, estado: res.estado, version: p ? p.version : 0,
  resultado_json: JSON.stringify(resultadoPrivado).slice(0, 60000),
  total_mxn: p ? p.total : 0, expira_en: p ? expira : '', nonce: p ? nonce : '',
  costo_usd: res.resumen_costos.total_usd, actualizado: ahoraIso
};
const fmt = n => Number(n).toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
let mensaje;
if (p) {
  const lineas = p.lineas.map(l => '• ' + l.cantidad + ' × ' + l.descripcion + ' = $' + fmt(l.importe)).join('\n');
  mensaje = '🧾 ' + p.etiqueta + ' — PapelSur (empresa ficticia)\nFolio: ' + res.caso_id + ' · versión ' + p.version + '\n\n' + lineas +
    '\n\nSubtotal: $' + fmt(p.subtotal) + '\nDescuento (' + (p.descuento_pct * 100) + '%): −$' + fmt(p.descuento) + '\nEnvío: $' + fmt(p.envio) +
    '\nIVA 16%: $' + fmt(p.iva) + '\nTOTAL: $' + fmt(p.total) + ' MXN\n\n' + p.resumen + '\n\nSupuestos:\n- ' + p.supuestos.join('\n- ') +
    '\n\nRevisada por el Agente 4. ¿Apruebas la orden de PRUEBA? Vence en ' + (res.minutos_expiracion || 30) + ' min.';
} else {
  mensaje = 'Folio ' + res.caso_id + ': ' + res.mensaje_usuario + (res.estado === 'requiere_aclaracion' ? '\nResponde con /nuevo y la solicitud completa.' : '');
}
return [{ json: {
  caso_id: res.caso_id, estado: res.estado, chat_id: chatDestino, mensaje: mensaje.slice(0, 4000),
  tiene_propuesta: p ? 1 : 0,
  cb_aprobar: p ? ('ap|' + res.caso_id + '|' + p.version + '|' + nonce) : '',
  cb_rechazar: p ? ('rc|' + res.caso_id + '|' + p.version + '|' + nonce) : '',
  fila_caso, filas_costos: res.costos
} }];
